"""The Gemini calls of the MPVI pipeline: structured output, retry with backoff, a cache by prompt, a log of every prompt and reply (design plan 8, LLM_CFG in src/task_config.py).

    caller = GeminiCaller(mode="cache_only")                     # tests and replays: only stored replies, the API is never called
    caller = GeminiCaller(mode="live")                           # a live run: always calls the API and stores the reply
    reply = caller("Prompt text", Plan, kind="plan", version="planner-v1")       # a dict that fits the Pydantic model's schema
    text = caller.text_call("Prompt text", image_rgb, kind="vlm", version="vlm-v1")   # a free-text reply about an image (the VLM completion checker)
    label_call = caller.bind("label", LLM_CFG["label_prompt_version"])           # (prompt, model) -> dict: what make_llm_labeler() wants
    caller.log                                                    # one dict per call: kind, model, versions, prompt, reply text, from_cache, attempts, seconds

Structured output: the Pydantic model's JSON schema is given to the SDK as `response_json_schema` (Gemini enforces it; the older `response_schema` field refuses the "additionalProperties": false that our extra="forbid" models produce); the reply text is parsed as JSON and returned as a dict, and the caller validates it
again with the model (src/mpvi_postprocess.py, src/mpvi_planner.py), so a reply that does not fit stops the plan.

Cache (LLM_CFG["cache_dir"], one JSON file per reply, written to a temporary file and renamed): the key is the SHA-256 of the model name, the prompt version, the schema's name and the whole
prompt text, i.e. of the instruction and the prompt version; a different model or prompt version never reuses a reply. An image call (text_call) adds the SHA-256 of the image's PNG bytes to the key
(the image is encoded with OpenCV's default PNG settings, which are deterministic), and the image is stored next to the reply as <key>.png. Modes: "cache_only" (default; a miss raises LLMCacheMiss and nothing is
sent anywhere), "cache_or_live" (read the cache, call on a miss and store), "live" (call every time, store the reply over the old one: the cache is bypassed for reading, and the new reply is
what later replays get).

Rate limits: a 429 or a server error (500, 503, 504) or a network error is retried up to LLM_CFG["max_retries"] times, waiting base * 2**retry plus up to a second of jitter, at least the
server's own "retry in Ns" hint, at most backoff_max_s. A 429 that names a per-day quota is not retried (waiting a minute does not help). Other errors (a bad key, a bad request) are not retried.

The API key (GEMINI_API_KEY from the environment, else from the secrets file) is never logged, printed or stored: it is not in the log or the cache, and it is masked in every error text.

Contents:
    LLMError, LLMEmptyReply, LLMCacheMiss, load_api_key(), cache_key(), LLMCache, GeminiCaller.
"""

import hashlib
import json
import os
import random
import re
import tempfile
import time
from pathlib import Path

from src.task_config import LLM_CFG

PROJECT_ROOT = Path(__file__).resolve().parent.parent
RETRY_CODES = (429, 500, 502, 503, 504)


class LLMError(RuntimeError):
    """A Gemini call failed for good (message with the key masked)."""


class LLMEmptyReply(LLMError):
    """The call went through but the reply has no text (a refusal, a blocked reply, an empty answer); not retried."""


class LLMCacheMiss(LLMError):
    """The cache has no stored reply for this prompt and the mode does not allow calling the API."""


def load_api_key(cfg=LLM_CFG):
    """Reads the API key from GEMINI_API_KEY, else from the secrets file.

    Args:
        cfg (dict): LLM_CFG ("secrets_file").

    Returns:
        str: The key. Never print or log it.

    Raises:
        LLMError: If there is none.
    """
    key = os.environ.get("GEMINI_API_KEY", "").strip()
    if not key:
        path = Path(os.path.expanduser(cfg["secrets_file"]))
        if path.is_file():
            for line in path.read_text().splitlines():
                name, _, value = line.strip().partition("=")
                if name.strip() == "GEMINI_API_KEY":
                    key = value.strip().strip("'\"")
    if not key:
        raise LLMError(f"no GEMINI_API_KEY in the environment or in {cfg['secrets_file']}")
    return key


def png_bytes(image_rgb):
    """Encodes an RGB image (H, W, 3) uint8 as PNG bytes (deterministic: the same pixels always give the same bytes).

    Args:
        image_rgb (numpy.ndarray): The image.

    Returns:
        bytes: The PNG file's content.
    """
    import cv2
    ok, buf = cv2.imencode(".png", cv2.cvtColor(image_rgb, cv2.COLOR_RGB2BGR))
    if not ok:
        raise LLMError("could not encode the image as PNG")
    return buf.tobytes()


def cache_key(model, version, schema_name, prompt, image_sha=None):
    """Gives the cache key of a call.

    Args:
        model (str): The pinned model name.
        version (str): The prompt version.
        schema_name (str): The response model's class name.
        prompt (str): The whole prompt text (it contains the instruction).
        image_sha (str or None): The SHA-256 of the image's PNG bytes for an image call. Defaults to None (no image; the key is then the same as before images existed).

    Returns:
        str: A hex SHA-256 digest.
    """
    parts = [model, version, schema_name, prompt] + ([image_sha] if image_sha else [])
    return hashlib.sha256(json.dumps(parts, ensure_ascii=False).encode()).hexdigest()


class LLMCache:
    """The stored replies, one JSON file per key."""

    def __init__(self, directory):
        """Sets the folder (made on the first write).

        Args:
            directory (str or Path): The cache folder; relative paths are from the project root.
        """
        d = Path(directory)
        self.dir = d if d.is_absolute() else PROJECT_ROOT / d

    def get(self, key):
        """Gives a stored record.

        Args:
            key (str): The cache key.

        Returns:
            dict or None: The record ({"key", "kind", "model", "version", "schema", "prompt", "reply_text", "created"}) or None.
        """
        path = self.dir / f"{key}.json"
        return json.loads(path.read_text()) if path.is_file() else None

    def put(self, key, record, image_png=None):
        """Stores a record, replacing an old one; the file is written whole to a temporary name and renamed (an interrupted write leaves the old file).

        Args:
            key (str): The cache key.
            record (dict): The record (JSON-serialisable).
            image_png (bytes or None): The image of an image call, stored as <key>.png (written before the record, so a record never points at a missing image).
        """
        self.dir.mkdir(parents=True, exist_ok=True)
        if image_png is not None:
            fd, tmp = tempfile.mkstemp(dir=self.dir, suffix=".tmp")
            with os.fdopen(fd, "wb") as f:
                f.write(image_png)
            os.replace(tmp, self.dir / f"{key}.png")
        fd, tmp = tempfile.mkstemp(dir=self.dir, suffix=".tmp")
        with os.fdopen(fd, "w") as f:
            json.dump(record, f, indent=1, ensure_ascii=False)
        os.replace(tmp, self.dir / f"{key}.json")


class GeminiCaller:
    """Calls Gemini with structured output, through the cache, with retries; keeps a log.

    Attributes:
        log (list[dict]): One entry per call (see the module docstring), in order; save it with the run.
        mode (str): "cache_only", "cache_or_live" or "live".
    """

    def __init__(self, cfg=LLM_CFG, mode=None, client=None, cache=None, say=print, sleep=time.sleep):
        """Sets up the caller; the client (and so the key) is made on the first live call.

        Args:
            cfg (dict): LLM_CFG. Defaults to it.
            mode (str or None): Overrides cfg["mode"].
            client (object or None): A google.genai.Client or a fake with client.models.generate_content(model=, contents=, config=). Defaults to a real client made on demand.
            cache (LLMCache or None): Defaults to the cache in cfg["cache_dir"].
            say (callable): Where progress lines go (never the key). Defaults to print.
            sleep (callable): The waiting function (a test replaces it). Defaults to time.sleep.
        """
        self.cfg = cfg
        self.mode = mode or cfg["mode"]
        if self.mode not in ("cache_only", "cache_or_live", "live"):
            raise ValueError(f"unknown LLM mode {self.mode!r}")
        self._client = client
        self.cache = cache or LLMCache(cfg["cache_dir"])
        self.say, self.sleep = say, sleep
        self.log = []
        self._images = {}
        self._key = None

    def __repr__(self):
        return f"GeminiCaller(model={self.cfg['model']!r}, mode={self.mode!r})"

    def _mask(self, text):
        """Hides the key in a text."""
        return text.replace(self._key, "***") if self._key else text

    def _get_client(self):
        if self._client is None:
            from google import genai
            from google.genai import types
            self._key = load_api_key(self.cfg)
            self._client = genai.Client(api_key=self._key, http_options=types.HttpOptions(timeout=int(self.cfg["timeout_s"] * 1000)))
        return self._client

    @staticmethod
    def _hint_s(text):
        """The server's own wait hint in an error text ("retry in 12.3s", retryDelay "12s"), or 0."""
        m = re.search(r"retry in ([\d.]+)\s*s", text) or re.search(r'retryDelay"?\s*[:=]\s*"?([\d.]+)s', text)
        return float(m.group(1)) if m else 0.0

    def _generate(self, prompt, response_model, system, image_png=None, choices=None):
        """One live call with retries; returns (reply text, attempts). Without a response model the reply is free text (or, with `choices`, exactly one of them: Gemini's enum output,
        response_mime_type "text/x.enum"); with an image the image comes first in the contents."""
        from google.genai import errors, types
        client = self._get_client()
        kw = {"temperature": self.cfg["temperature"], "thinking_config": types.ThinkingConfig(thinking_budget=self.cfg["thinking_budget"])}
        if response_model is not None:
            kw.update(response_mime_type="application/json", response_json_schema=response_model.model_json_schema())
        elif choices:
            kw.update(response_mime_type="text/x.enum", response_schema=types.Schema(type=types.Type.STRING, enum=list(choices)))
        contents = prompt if image_png is None else [types.Part.from_bytes(data=image_png, mime_type="image/png"), prompt]
        if system:
            kw["system_instruction"] = system
        config = types.GenerateContentConfig(**kw)
        for attempt in range(self.cfg["max_retries"] + 1):
            try:
                resp = client.models.generate_content(model=self.cfg["model"], contents=contents, config=config)
                text = resp.text
                if not text:
                    raise LLMEmptyReply(f"empty reply from {self.cfg['model']} (finish reason {getattr(resp.candidates[0], 'finish_reason', '?') if getattr(resp, 'candidates', None) else 'none'})")
                return text, attempt + 1
            except LLMError:
                raise
            except Exception as e:                                    # noqa: BLE001 - classified below; anything not retryable is raised with the key masked
                msg = self._mask(str(e))
                code = getattr(e, "code", None) if isinstance(e, errors.APIError) else None
                network = not isinstance(e, errors.APIError) and type(e).__module__.split(".")[0] in ("httpx", "httpcore", "requests", "urllib3", "ssl", "socket")
                per_day = code == 429 and re.search(r"PerDay|per day", msg, re.I) is not None
                if per_day or not (code in RETRY_CODES or network):
                    raise LLMError(f"{type(e).__name__}{f' ({code})' if code else ''}: {msg[:600]}") from None
                if attempt >= self.cfg["max_retries"]:
                    raise LLMError(f"gave up after {attempt + 1} tries: {type(e).__name__}{f' ({code})' if code else ''}: {msg[:300]}") from None
                wait = min(self.cfg["backoff_max_s"], max(self._hint_s(msg) + 1.0, self.cfg["backoff_base_s"] * 2 ** attempt) + random.uniform(0.0, 1.0))
                self.say(f"[llm] {type(e).__name__}{f' ({code})' if code else ''}: retry {attempt + 1}/{self.cfg['max_retries']} in {wait:.1f} s")
                self.sleep(wait)
        raise LLMError("unreachable")

    def _run(self, prompt, response_model, kind, version, system, image_png=None, choices=None):
        """The shared call: cache or live by the mode, a log entry. Returns the reply text."""
        sha = hashlib.sha256(image_png).hexdigest() if image_png is not None else None
        schema_name = response_model.__name__ if response_model is not None else "text"
        key = cache_key(self.cfg["model"], version, schema_name, prompt, sha)
        t0 = time.time()
        rec = None if self.mode == "live" else self.cache.get(key)
        from_cache, attempts = rec is not None, 0
        if rec is None:
            if self.mode == "cache_only":
                raise LLMCacheMiss(f"no stored reply for this {kind} call (key {key[:12]}, model {self.cfg['model']}, version {version}"
                                   + (f", image {sha[:12]}" if sha else "") + "); the mode is cache_only, nothing was sent")
            text, attempts = self._generate(prompt, response_model, system, image_png, choices)
            rec = {"key": key, "kind": kind, "model": self.cfg["model"], "version": version, "schema": schema_name, "prompt": prompt, "reply_text": text,
                   "created": time.strftime("%Y-%m-%dT%H:%M:%S")}
            if sha:
                rec["image_sha256"] = sha
            self.cache.put(key, rec, image_png)
        entry = {"kind": kind, "model": rec["model"], "version": version, "schema": schema_name, "key": key, "from_cache": from_cache, "attempts": attempts,
                 "seconds": round(time.time() - t0, 3), "prompt": prompt, "reply_text": rec["reply_text"]}
        if sha:
            entry["image_sha256"] = sha
            self._images[sha] = image_png
        self.log.append(entry)
        self.say(f"[llm] {kind} call {'from the cache' if from_cache else f'live, {entry['seconds']:.1f} s, {attempts} try(ies)'} (model {rec['model']}, version {version}, key {key[:12]}"
                 + (f", image {sha[:12]}" if sha else "") + ")")
        return rec["reply_text"]

    def __call__(self, prompt, response_model, kind="call", version="v0", system=None):
        """Makes one structured call (from the cache or live, by the mode).

        Args:
            prompt (str): The whole prompt text.
            response_model (type): The Pydantic model of the reply (the schema Gemini must follow).
            kind (str): A label for the log ("plan", "label").
            version (str): The prompt version (part of the cache key).
            system (str or None): An optional system instruction (not part of the key; keep it fixed per version).

        Returns:
            dict: The reply parsed from JSON.

        Raises:
            LLMCacheMiss: In "cache_only" mode with no stored reply.
            LLMError: When the call fails for good or the reply is not JSON.
        """
        text = self._run(prompt, response_model, kind, version, system)
        try:
            return json.loads(text)
        except json.JSONDecodeError as e:
            raise LLMError(f"the {kind} reply is not JSON: {e}: {text[:200]!r}") from None

    def text_call(self, prompt, image_rgb, kind="vlm", version="v0", system=None, choices=None):
        """Asks about an image and gets a text answer (the VLM completion checker; the paper's prompt asks for a YES or NO sentence).

        Args:
            prompt (str): The whole prompt text.
            image_rgb (numpy.ndarray): The image, (H, W, 3) uint8 RGB; it is sent as PNG and its SHA-256 is part of the cache key.
            kind (str): A label for the log.
            version (str): The prompt version (part of the cache key).
            system (str or None): An optional system instruction.
            choices (list[str] or None): If given, Gemini's enum output restricts the reply to exactly one of these strings. NOT part of the cache key (a stored free-text reply with the same
                prompt and image is the same entry), so the caller must check the reply itself. Defaults to None (free text).

        Returns:
            str: The reply text.

        Raises:
            LLMCacheMiss: In "cache_only" mode with no stored reply for this image and prompt.
            LLMError: When the call fails for good.
        """
        return self._run(prompt, None, kind, version, system, png_bytes(image_rgb), choices)

    def bind(self, kind, version, system=None):
        """Gives a two-argument function (prompt, response_model) -> dict for make_llm_labeler() and make_llm_planner().

        Args:
            kind (str): The log label.
            version (str): The prompt version.
            system (str or None): The system instruction.

        Returns:
            callable: structured_call(prompt, response_model).
        """
        return lambda prompt, response_model: self(prompt, response_model, kind=kind, version=version, system=system)

    def save_log(self, path):
        """Writes the log (every prompt and reply, no key) as JSON, whole to a temporary file and renamed; the images of image calls go to vlm_images/<sha>.png next to it.

        Args:
            path (str or Path): The file.
        """
        path = Path(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        if self._images:                                              # the images of the image calls, one PNG per hash, next to the log
            img_dir = path.parent / "vlm_images"
            img_dir.mkdir(parents=True, exist_ok=True)
            for sha, png in self._images.items():
                (img_dir / f"{sha}.png").write_bytes(png)
        tmp = path.with_suffix(".tmp")
        tmp.write_text(json.dumps({"model": self.cfg["model"], "mode": self.mode, "calls": self.log}, indent=1, ensure_ascii=False))
        os.replace(tmp, path)
